# -*- coding: utf-8 -*-
r"""내장 문자 — 등록 없이 바로 쓰는 규칙적인 기호들.

라이브러리(서식/문자/템플릿)와 달리 사용자가 등록하지 않아도 되는, 개수 많고
규칙적인 문자들을 코드에 내장한다. 마크다운 변환에서 \원1\ \로마3\ 처럼 호출하고,
물감 설정의 '특수기호' 탭에 내가 등록한 기호와 함께 격자로 보인다.

각 항목: (label, text, group)
  label = \label\ 로 부를 이름 (사용자 등록 항목과 이름이 겹치면 사용자 것이 우선)
  text  = 삽입될 실제 문자
  group = 검색·분류용 이름
"""

# 원문자 자모 순서 (㉠=ㄱ … ㉭=ㅎ)
_KR_CONSONANTS = list("ㄱㄴㄷㄹㅁㅂㅅㅇㅈㅊㅋㅌㅍㅎ")

# 괄호 한글 음절 순서 (㈎=가 … ㈛=하)
_KR_SYLLABLES = list("가나다라마바사아자차카타파하")

# 그리스 문자 이름 (소문자·대문자 공용). 과학 답안·문제지에서 상수·각·변수로 상시 쓴다.
_GREEK_NAMES = [
    "알파", "베타", "감마", "델타", "엡실론", "제타", "에타", "세타",
    "이오타", "카파", "람다", "뮤", "뉴", "크시", "오미크론", "파이",
    "로", "시그마", "타우", "웁실론", "피", "카이", "프시", "오메가",
]
_GREEK_LOWER = "αβγδεζηθικλμνξοπρστυφχψω"
_GREEK_UPPER = "ΑΒΓΔΕΖΗΘΙΚΛΜΝΞΟΠΡΣΤΥΦΧΨΩ"


def _build():
    items = []

    # ── 원문자: 숫자 ①~⑳ ──
    for i in range(20):
        items.append((f"원{i+1}", chr(0x2460 + i), "원문자·숫자"))
    # ── 원문자: 알파벳 ⓐ~ⓩ ──
    for i in range(26):
        items.append((f"원{chr(ord('a')+i)}", chr(0x24D0 + i), "원문자·알파벳"))
    # ── 원문자: 한글 자모 ㉠~㉭ ──
    for i, c in enumerate(_KR_CONSONANTS):
        items.append((f"원{c}", chr(0x3260 + i), "원문자·한글"))

    # ── 로마 숫자 Ⅰ~Ⅻ ──
    for i in range(12):
        items.append((f"로마{i+1}", chr(0x2160 + i), "로마숫자"))

    # ── 낫표 (양쪽 방향 둘 다 = 쌍) + 방향별 ──
    items.append(("홑낫표", "「」", "낫표"))
    items.append(("겹낫표", "『』", "낫표"))
    items.append(("여는홑낫표", "「", "낫표"))
    items.append(("닫는홑낫표", "」", "낫표"))
    items.append(("여는겹낫표", "『", "낫표"))
    items.append(("닫는겹낫표", "』", "낫표"))

    # ── 로마 숫자 소문자 ⅰ~ⅻ (표 항목 번호에 자주 쓴다) ──
    for i in range(12):
        items.append((f"작은로마{i+1}", chr(0x2170 + i), "로마숫자소문자"))

    # ── 괄호 숫자 ⑴~⒇ ──
    for i in range(20):
        items.append((f"괄호{i+1}", chr(0x2474 + i), "괄호숫자"))
    # ── 괄호 한글 자모 ㈀~㈍ ──
    for i, c in enumerate(_KR_CONSONANTS):
        items.append((f"괄호{c}", chr(0x3200 + i), "괄호한글"))
    # ── 괄호 한글 음절 ㈎~㈛ (문항 보기 번호로 흔하다) ──
    for i, c in enumerate(_KR_SYLLABLES):
        items.append((f"괄호{c}", chr(0x320E + i), "괄호한글"))
    # ── 괄호 한자 숫자 ㈠~㈩ ──
    for i in range(10):
        items.append((f"괄호한자{i+1}", chr(0x3220 + i), "괄호한자"))

    # ── 그리스 문자 (과학 상수·각·변수) ──
    for name, low, up in zip(_GREEK_NAMES, _GREEK_LOWER, _GREEK_UPPER):
        items.append((name, low, "그리스"))
        items.append((f"대문자{name}", up, "그리스"))
    items.append(("끝시그마", "ς", "그리스"))

    # ── 수학 기호 (연산·부등호·집합·논리·미적분) ──
    for label, text in [
        ("곱하기", "×"), ("나누기", "÷"), ("플러스마이너스", "±"), ("마이너스플러스", "∓"),
        ("같지않음", "≠"), ("작거나같음", "≤"), ("크거나같음", "≥"), ("거의같음", "≒"),
        ("항등", "≡"), ("무한대", "∞"), ("따라서", "∴"), ("왜냐하면", "∵"),
        ("루트", "√"), ("시그마합", "∑"), ("파이곱", "∏"), ("적분", "∫"),
        ("비례", "∝"), ("수직", "⊥"), ("각", "∠"), ("직각", "∟"), ("닮음", "∽"),
        ("훨씬작음", "≪"), ("훨씬큼", "≫"),
        ("부분집합", "⊂"), ("포함집합", "⊃"), ("부분집합같음", "⊆"), ("포함집합같음", "⊇"),
        ("합집합", "∪"), ("교집합", "∩"), ("원소", "∈"), ("원소포함", "∋"),
        ("모든", "∀"), ("존재", "∃"), ("부정", "¬"), ("그리고", "∧"), ("또는", "∨"),
        ("나블라", "∇"), ("편미분", "∂"), ("선적분", "∮"),
        ("도", "°"), ("분기호", "′"), ("초기호", "″"), ("퍼밀", "‰"),
        ("로그", "㏒"), ("자연로그", "㏑"),
    ]:
        items.append((label, text, "수학"))

    # ── 화살표 (반응식·흐름도·이동 방향) ──
    for label, text in [
        ("오른쪽화살표", "→"), ("왼쪽화살표", "←"), ("위쪽화살표", "↑"), ("아래쪽화살표", "↓"),
        ("좌우화살표", "↔"), ("상하화살표", "↕"),
        ("오른쪽쌍화살표", "⇒"), ("왼쪽쌍화살표", "⇐"), ("좌우쌍화살표", "⇔"),
        ("위쪽쌍화살표", "⇑"), ("아래쪽쌍화살표", "⇓"),
        ("오른위화살표", "↗"), ("오른아래화살표", "↘"), ("왼아래화살표", "↙"), ("왼위화살표", "↖"),
        ("오른쪽속찬화살표", "⇨"), ("왼쪽속찬화살표", "⇦"),
        ("위쪽속찬화살표", "⇧"), ("아래쪽속찬화살표", "⇩"),
        ("왼꺾임화살표", "↰"), ("오른꺾임화살표", "↱"),
        ("좌우나란화살표", "⇄"), ("상하나란화살표", "⇅"),
    ]:
        items.append((label, text, "화살표"))

    # ── 도형·기호 (보기 표시·강조 머리표) ──
    for label, text in [
        ("검은사각", "■"), ("흰사각", "□"), ("겹사각", "▣"),
        ("가로줄사각", "▤"), ("세로줄사각", "▥"), ("격자사각", "▦"),
        ("오른빗금사각", "▧"), ("왼빗금사각", "▨"), ("교차빗금사각", "▩"), ("점무늬사각", "▒"),
        ("검은동그라미", "●"), ("흰동그라미", "○"), ("겹동그라미", "◎"), ("속찬겹동그라미", "◉"),
        ("흰마름모", "◇"), ("검은마름모", "◆"), ("겹마름모", "◈"),
        ("흰삼각", "△"), ("검은삼각", "▲"), ("흰역삼각", "▽"), ("검은역삼각", "▼"),
        ("흰왼삼각", "◁"), ("검은왼삼각", "◀"), ("흰오른삼각", "▷"), ("검은오른삼각", "▶"),
        ("흰별", "☆"), ("검은별", "★"),
        ("스페이드", "♠"), ("클로버", "♣"), ("하트", "♥"), ("다이아", "♦"),
        ("흰스페이드", "♤"), ("흰클로버", "♧"), ("흰하트", "♡"),
        ("작은검은사각", "▪"), ("작은흰사각", "▫"),
    ]:
        items.append((label, text, "도형"))

    # ── 단위 (실험·측정값 표기) ──
    for label, text in [
        ("밀리미터", "㎜"), ("센티미터", "㎝"), ("킬로미터", "㎞"),
        ("제곱미터", "㎡"), ("제곱킬로미터", "㎢"), ("세제곱미터", "㎥"),
        ("밀리리터", "㎖"), ("데시리터", "㎗"), ("리터", "ℓ"), ("킬로리터", "㎘"),
        ("마이크로그램", "㎍"), ("밀리그램", "㎎"), ("킬로그램", "㎏"), ("시시", "㏄"),
        ("칼로리", "㎈"), ("킬로칼로리", "㎉"), ("섭씨", "℃"), ("화씨", "℉"),
        ("헤르츠", "㎐"), ("킬로헤르츠", "㎑"), ("메가헤르츠", "㎒"), ("기가헤르츠", "㎓"),
        ("파스칼", "㎩"), ("킬로파스칼", "㎪"), ("메가파스칼", "㎫"), ("기가파스칼", "㎬"),
        ("킬로볼트", "㎸"), ("킬로와트", "㎾"), ("데시벨", "㏈"), ("헥타르", "㏊"),
        ("초속", "㎧"), ("가속도", "㎨"),
        ("피코초", "㎰"), ("나노초", "㎱"), ("마이크로초", "㎲"), ("밀리초", "㎳"),
        ("피코볼트", "㎴"), ("나노볼트", "㎵"), ("마이크로볼트", "㎶"), ("밀리볼트", "㎷"),
        ("옴", "Ω"), ("킬로옴", "㏀"), ("메가옴", "㏁"),
        ("피코암페어", "㎀"), ("마이크로암페어", "㎂"), ("밀리암페어", "㎃"), ("킬로암페어", "㎄"),
        ("옹스트롬", "Å"),
    ]:
        items.append((label, text, "단위"))

    # ── 문장부호 (안내문·공문에서 쓰는 표시) ──
    for label, text in [
        ("참고표", "※"), ("말줄임표", "…"), ("두점줄임", "‥"),
        ("가운데줄", "─"), ("긴줄", "―"), ("물결", "~"), ("물결기호", "∼"),
        ("가운뎃점", "·"), ("일본가운뎃점", "・"),
        ("문단기호", "¶"), ("절기호", "§"), ("칼표", "†"), ("겹칼표", "‡"),
        ("겹따옴표기호", "˝"),
        ("여는작은따옴표", "‘"), ("닫는작은따옴표", "’"),
        ("여는큰따옴표", "“"), ("닫는큰따옴표", "”"),
        ("번호기호", "№"), ("전화기호", "℡"), ("주식회사", "㈜"),
        ("전화", "☎"), ("흰전화", "☏"), ("우편번호", "㉿"),
    ]:
        items.append((label, text, "문장부호"))

    # ── 괄호 (제목·인용 표기) ──
    items.append(("홑꺾쇠", "〈〉", "괄호"))
    items.append(("겹꺾쇠", "《》", "괄호"))
    for label, text in [
        ("여는홑꺾쇠", "〈"), ("닫는홑꺾쇠", "〉"),
        ("여는겹꺾쇠", "《"), ("닫는겹꺾쇠", "》"),
        ("여는두꺼운괄호", "【"), ("닫는두꺼운괄호", "】"),
        ("여는거북괄호", "〔"), ("닫는거북괄호", "〕"),
        ("여는이중거북괄호", "〖"), ("닫는이중거북괄호", "〗"),
        ("여는전각중괄호", "｛"), ("닫는전각중괄호", "｝"),
        ("여는전각대괄호", "［"), ("닫는전각대괄호", "］"),
        ("여는전각소괄호", "（"), ("닫는전각소괄호", "）"),
    ]:
        items.append((label, text, "괄호"))

    # ── 분수·첨자 (화학식·지수 표기) ──
    for label, text in [
        ("이분의일", "½"), ("삼분의일", "⅓"), ("삼분의이", "⅔"),
        ("사분의일", "¼"), ("사분의삼", "¾"), ("팔분의일", "⅛"),
        ("위첨자1", "¹"), ("위첨자2", "²"), ("위첨자3", "³"), ("위첨자4", "⁴"),
        ("아래첨자1", "₁"), ("아래첨자2", "₂"), ("아래첨자3", "₃"), ("아래첨자4", "₄"),
    ]:
        items.append((label, text, "분수·첨자"))

    # ── 화폐 ──
    for label, text in [
        ("원화", "₩"), ("달러", "$"), ("엔화", "¥"),
        ("유로", "€"), ("파운드", "£"), ("센트", "¢"),
    ]:
        items.append((label, text, "화폐"))

    # ── 음악·기타 (체크표·성별기호 등 잡다한 표시) ──
    for label, text in [
        ("팔분음표", "♪"), ("사분음표", "♩"), ("이음음표", "♬"),
        ("플랫", "♭"), ("샾", "♯"),
        ("남성", "♂"), ("여성", "♀"),
        ("왼손가리킴", "☜"), ("오른손가리킴", "☞"), ("웃는얼굴", "☺"),
        ("체크", "✓"), ("굵은체크", "✔"), ("가위표", "✕"), ("굵은가위표", "✖"),
    ]:
        items.append((label, text, "음악·기타"))

    return items


BUILTINS = _build()

# 라벨 → 텍스트 빠른 조회
BUILTIN_LOOKUP = {label: text for label, text, _ in BUILTINS}
assert len(BUILTIN_LOOKUP) == len(BUILTINS), "Duplicate builtin labels detected"


def search(query):
    """query가 label/text/group 어디에든 들어가면 매치. 빈 query면 전체."""
    q = (query or "").strip().lower()
    if not q:
        return list(BUILTINS)
    out = []
    for label, text, group in BUILTINS:
        if q in label.lower() or q in text.lower() or q in group.lower():
            out.append((label, text, group))
    return out
